fn extract_agent_memory_items(input: &str) -> Vec<String> {
    let text = input.trim();
    let lower = text.to_lowercase();
    let mut out = Vec::new();

    for marker in ["remember that ", "remember "] {
        if let Some(rest) = lower
            .find(marker)
            .map(|idx| text[idx + marker.len()..].trim())
        {
            if !rest.is_empty() {
                out.push(rest.trim_matches(['.', '!', '?']).to_string());
                return out;
            }
        }
    }

    for marker in [
        "my name is ",
        "i am ",
        "i'm ",
        "i like ",
        "i love ",
        "i prefer ",
        "i use ",
    ] {
        if let Some(rest) = lower.find(marker).map(|idx| text[idx..].trim()) {
            if rest.len() <= 160 {
                out.push(format!("User said: {}", rest.trim_matches(['.', '!', '?'])));
                return out;
            }
        }
    }

    out
}


fn main() { std::panic::set_hook(Box::new(|_| {})); assert_eq!(extract_agent_memory_items("remember tea"),vec!["tea"]); assert!(std::panic::catch_unwind(|| extract_agent_memory_items("İremember я")).is_err()); println!("ASCII control passed; Unicode lowercase-offset panic reproduced"); }
